if (fork() === 0) {          // first child
    if (fork() === 0) {      // grandchild, this becomes the daemon
        // continues running here, now fully independent
    } else {
        exit(0);              // first child exits immediately
    }
} else {
    wait(NULL);                // original parent collects the first child
}
// the grandchild is now an orphan, reparented to init automatically

